		"recommended_fix": "Увеличить cgroup memory limit и настроить GOMEMLIMIT=90%",
		"confidence": 0.98
	}`)

	analysis, err := ParseStructuredOutput(sampleModelOutput)
	if err != nil {
		panic(err)
